REFINEMENTS = {86: [('H4', [88, 94, 99, 100, 109, 116, 117, 118, 120, 126, 130, 136])], 87: [('H4', [100, 109, 119, 121, 125])], 88: [('H5', [89, 90, 91, 92, 93])], 94: [('H5', [95, 96, 97, 98])], 100: [('H5', [101, 102, 103, 104, 105, 106, 107, 108])], 109: [('H4', [110, 111, 112, 113, 114, 115])], 120: [('H4', [121, 122, 123, 124])], 124: [('H4', [137])], 126: [('H4', [127]), ('H4', [128]), ('H4', [129])], 130: [('H5', [131, 132, 133, 134, 135])]}

def build_model():
    agents = {
        'system': Agent('Maintenance logging system', AgentType.SOFTWARE_AGENT),
        'technician': Agent('Maintenance technician', AgentType.ENVIRONMENT_AGENT),
        'supervisor': Agent('Shift supervisor or maintenance lead', AgentType.ENVIRONMENT_AGENT),
        'ehs': Agent('EHS coordinator', AgentType.ENVIRONMENT_AGENT),
        'team': Agent('Maintenance team members - individual accountability to confirm', AgentType.ENVIRONMENT_AGENT),
        'operator': Agent('Worker using tablet', AgentType.ENVIRONMENT_AGENT),
    }
    types = {'AchieveGoal': AchieveGoal, 'MaintainGoal': MaintainGoal,
             'AvoidGoal': AvoidGoal, 'SoftGoal': SoftGoal}
    goals = {}
    for gid, record in SOURCE_GOALS.items():
        actor = record['agent']
        performances = None
        if actor:
            category = (OperationCategory.SOFTWARE_TO_BE_OPERATION if actor == 'system'
                        else OperationCategory.ENVIRONMENT_OPERATION)
            performances = [PerformanceLink(agents[actor], Operation(record['text'], category))]
        goals[gid] = types[record['type']](
            name=f"{gid}: {record['text']}", performs=performances,
            leaf=actor is not None, annotation=record['category'])
    for parent, alternatives in REFINEMENTS.items():
        goals[f'G-{parent}'].disjunctions = [
            Refinement(complete=False, children=[goals[f'G-{c}'] for c in children], annotation=code)
            for code, children in alternatives]
    return goals

def render_model():
    goals = build_model()
    graph = generate_graph([goals['G-86'], goals['G-87']], [])
    graph += '\nclassDef inferred fill:#fff176,stroke:#000\n'
    for gid, record in SOURCE_GOALS.items():
        if record['inferred']:
            graph += f"class {goals[gid].get_node_id()} inferred\n"
    return graph

if __name__ == '__main__':
    graph = render_model()
    output_dir = Path(__file__).resolve().parent
    (output_dir / 'goal_model_Rob.mmd').write_text(graph, encoding='utf-8')
    link = generate_pako_link(graph, 'edit')
    (output_dir / 'mermaid_Rob.txt').write_text(link + '\n', encoding='utf-8')
    print(link)
